// HasAllocationRules filters parents that have a matching AllocationRules using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to AllocationRules).
func (w categoryWhereR[Q]) HasAllocationRules(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(AllocationRules.NameExpr()),
		sm.Where(AllocationRules.Columns.HouseholdID.EQ(w.cols.HouseholdID)),
		sm.Where(AllocationRules.Columns.CategoryID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

