// LoadAllocationRules loads the category's AllocationRules into the .R struct
func (o *Category) LoadAllocationRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.AllocationRules = nil
	o.R.Loaded.AllocationRules = false

	related, err := o.AllocationRules(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Category = o
		rel.R.Loaded.Category = true
	}

	o.R.AllocationRules = related
	o.R.Loaded.AllocationRules = true
	return nil
}

