// LoadHousehold loads the category's Household into the .R struct
func (os CategorySlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	categoryByKey := make(map[uuid.UUID][]*Category, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		categoryByKey[o.HouseholdID] = append(categoryByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := categoryByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.Categories = append(rel.R.Categories, o)

			o.R.Household = rel

		}
	}

	return nil
}

